 export const TASA_IVA = 0.13;

+// Tasa de IVA configurable por entorno: TASA_IVA, número entre 0 y 1. Sin definir (o vacía) → 0.13.
+export function tasaIva(env = process.env) {
+  const crudo = env.TASA_IVA;
+  if (crudo === undefined || crudo === "") return TASA_IVA;
+  const tasa = /^\s*\d*\.?\d+\s*$/.test(crudo) ? Number(crudo) : NaN;
+  if (!Number.isFinite(tasa) || tasa < 0 || tasa > 1) {
+    throw new RangeError(`TASA_IVA inválida: "${crudo}" (debe ser un número entre 0 y 1)`);
+  }
+  return tasa;
+}
